	txTimestamp, err := ctx.GetStub().GetTxTimestamp()
	if err != nil {
		return err
	}
	txTime := time.Unix(txTimestamp.Seconds, int64(txTimestamp.Nanos)).Format(time.RFC3339)

	// Use deterministic timestamp for both note content and key
	compositeNote := fmt.Sprintf("%s (recorded at %s)", note, txTime)
	noteKey := "NOTE_" + recordID + "_" + txTime

	return ctx.GetStub().PutState(noteKey, []byte(compositeNote))
}
```

