if len(updateJSON) == 0 {
    return fmt.Errorf("update JSON cannot be empty")
}
if len(updates) == 0 {
    return fmt.Errorf("no updates provided")
}

// Validate zone and item IDs
for zoneID, itemUpdates := range updates {
    if strings.TrimSpace(zoneID) == "" {
        return fmt.Errorf("zone ID cannot be empty")
    }
    for itemID, qtyDelta := range itemUpdates {
        if strings.TrimSpace(itemID) == "" {
            return fmt.Errorf("item ID cannot be empty")
        }
        // Optional: validate quantity bounds
        if qtyDelta < -1000000 || qtyDelta > 1000000 {
            return fmt.Errorf("quantity delta out of bounds: %d", qtyDelta)
        }
    }
}

// In MergeZones
if strings.TrimSpace(targetZoneID) == "" {
    return fmt.Errorf("target zone ID cannot be empty")
}
if len(sourceZoneIDs) == 0 {
    return fmt.Errorf("no source zones provided")
}
```

